const dictionaries: Record<QaLanguage, QaMessages> = { ru, en };
let current: QaLanguage = "ru";

/** Switches the language of qt(); called by locales/setLanguage. Unknown values fall back to Russian. */
export function setQaLanguage(language: QaLanguage): void {
  current = language === "en" ? "en" : "ru";
}

export function getQaLanguage(): QaLanguage {
  return current;
}

/** Texts of the current language. */
export function qt(): QaMessages {
  return dictionaries[current];
}
